#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <chrono>
#include "../vote-cuda/kernels.h"
#include "case_table.h"
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA%s\n",cudaGetErrorString(e));exit(3);}}while(0)
std::vector<uint32_t>load(const char*n){std::ifstream f(n,std::ios::binary|std::ios::ate);if(!f)exit(4);std::vector<uint32_t>v(f.tellg()/4);f.seekg(0);f.read((char*)v.data(),v.size()*4);return v;}
int main(){auto inputs=load("inputs_u32.bin"),gold=load("oracle_u32.bin");bool all=true;for(int trial=0;trial<=5;trial++){std::vector<uint32_t>prefix,outputs;std::vector<double>times;size_t bad=0;bool ok=true;for(auto a:CASES){uint32_t *di=nullptr,*dout=nullptr;uint8_t*info=nullptr;std::vector<uint32_t>ih,oh,before,answer;std::vector<uint8_t>bh;if(a.op==2){bh.assign(a.output_count+32,0xa5);for(int t=0;t<96;t++)for(int f=0;f<3;f++)bh[16+3*t+f]=(a.initial_mode==1&&t%2==0&&f==2);CK(cudaMalloc(&info,bh.size()));CK(cudaMemcpy(info,bh.data(),bh.size(),cudaMemcpyHostToDevice));before.assign(bh.begin(),bh.end());}else{ih.assign(a.n+32,0xcafebabe);std::copy(inputs.begin()+a.input_offset,inputs.begin()+a.input_offset+a.n,ih.begin()+16);oh.assign(a.n+32,0xcafebabe);std::fill(oh.begin()+16,oh.begin()+16+a.n,0xdeadbeef);CK(cudaMalloc(&di,ih.size()*4));CK(cudaMalloc(&dout,oh.size()*4));CK(cudaMemcpy(di,ih.data(),ih.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dout,oh.data(),oh.size()*4,cudaMemcpyHostToDevice));before.resize(oh.size());CK(cudaMemcpy(before.data(),dout,oh.size()*4,cudaMemcpyDeviceToHost));ok=ok&&before==oh;}
 auto launch=[&](){if(a.op==0)VoteAnyKernel1<<<1,a.n>>>(di+16,dout+16,a.repeat);else if(a.op==1)VoteAllKernel2<<<1,a.n>>>(di+16,dout+16,a.repeat);else VoteAnyKernel3<<<1,a.n>>>((bool*)(info+16),32,a.repeat);};if(trial==0){launch();CK(cudaDeviceSynchronize());cudaFree(di);cudaFree(dout);cudaFree(info);continue;}
 if(a.op==2){std::vector<uint8_t>check(bh.size());CK(cudaMemcpy(check.data(),info,bh.size(),cudaMemcpyDeviceToHost));ok=ok&&check==bh;before.assign(check.begin(),check.end());}CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();launch();CK(cudaDeviceSynchronize());times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count());if(a.op==2){std::vector<uint8_t>v(bh.size());CK(cudaMemcpy(v.data(),info,v.size(),cudaMemcpyDeviceToHost));answer.assign(v.begin(),v.end());}else{std::vector<uint32_t>v(ih.size());CK(cudaMemcpy(v.data(),di,v.size()*4,cudaMemcpyDeviceToHost));ok=ok&&v==ih;prefix.insert(prefix.end(),v.begin(),v.end());answer.resize(oh.size());CK(cudaMemcpy(answer.data(),dout,oh.size()*4,cudaMemcpyDeviceToHost));}prefix.insert(prefix.end(),before.begin(),before.end());for(int i=0;i<a.output_count+32;i++){uint32_t ref=i<16||i>=a.output_count+16?(a.op==2?0xa5:0xcafebabe):gold[a.oracle_offset+i-16];bad+=answer[i]!=ref;}outputs.insert(outputs.end(),answer.begin(),answer.end());cudaFree(di);cudaFree(dout);cudaFree(info);}
 if(trial==0)continue;ok=ok&&bad==0;all=all&&ok;prefix.insert(prefix.end(),outputs.begin(),outputs.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)prefix.data(),prefix.size()*4);double total=0;for(auto t:times)total+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"artifact_word_mismatches\":%zu,\"timing_region\":\"sum48_singlelaunch_fullwarp_vote_hostwindows\",\"jit_excluded\":true,\"path_times_seconds\":[",trial,total,ok?"true":"false",prefix.size(),bad);for(size_t i=0;i<times.size();i++)printf("%s%.12g",i?",":"",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),prefix.size());}puts(all?"PASS":"FAIL");return all?0:2;}
